import argparse
import json
import os
import subprocess
import time
from collections import defaultdict

class JobSpool:
    def __init__(self, state_file):
        self.state_file = state_file
        self.state = self._load_state()
        self.next_id = max(self.state.get('pending', {}).keys(), default=0) + 1

    def _load_state(self):
        if os.path.exists(self.state_file):
            with open(self.state_file, 'r') as f:
                return json.load(f)
        return {
            'pending': {},
            'done': defaultdict(int),
            'failed': defaultdict(int)
        }

    def _save_state(self):
        with open(self.state_file, 'w') as f:
            json.dump(self.state, f)

    def add(self):
        while True:
            line = input().strip()
            if not line:
                break
            self.state['pending'][self.next_id] = line
            self.next_id += 1
            print(f"added {self.next_id - 1}")
        self._save_state()

    def run(self, rate):
        jobs = sorted(self.state['pending'].items())
        start_time = time.time()
        last_start = 0
        for job_id, cmd in jobs:
            if time.time() - last_start > 1.0:
                last_start = time.time()
                if time.time() - start_time > 1.0:
                    break
            try:
                result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
                self.state['done'][job_id] = 0
                print(f"ran {job_id} 0")
            except subprocess.CalledProcessError as e:
                self.state['failed'][job_id] = e.returncode
                print(f"ran {job_id} {e.returncode}")
            del self.state['pending'][job_id]
            self._save_state()
            if time.time() - last_start > 1.0:
                last_start = time.time()
                if time.time() - start_time > 1.0:
                    break
        self._save_state()

    def status(self):
        pending = len(self.state['pending'])
        done = sum(self.state['done'].values())
        failed = sum(self.state['failed'].values())
        print(f"pending={pending} done={done} failed={failed}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--state', required=True, help='State file for the spool')
    subparsers = parser.add_subparsers(dest='command', required=True)

    add_parser = subparsers.add_parser('add')
    add_parser.set_defaults(func=JobSpool._add)

    run_parser = subparsers.add_parser('run')
    run_parser.add_argument('--rate', type=int, required=True, help='Number of jobs per second')
    run_parser.set_defaults(func=JobSpool._run)

    status_parser = subparsers.add_parser('status')
    status_parser.set_defaults(func=JobSpool._status)

    args = parser.parse_args()
    spool = JobSpool(args.state)
    if args.command == 'add':
        spool.add()
    elif args.command == 'run':
        spool.run(args.rate)
    elif args.command == 'status':
        spool.status()

if __name__ == '__main__':
    main()
